                    case 'B': // byte
                    case 'C': // char
                    case 'F': // float
                    case 'I': // int
                    case 'S': // short
                    case 'Z': // boolean
                        index++;
                        popCategory1();
                        break;
                    case 'D': // double
                    case 'J': // long
                        index++;
                        popCategory2();
                        break;
                    case 'L': // reference
                    case '[': // array
                        index = argsDescriptor.indexOf(';', index) + 1;
                        popCategory1();
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
            }
        } else {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
    } else {
        // If it's not a method descriptor, treat it as a field descriptor and pop accordingly
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                popCategory1();
                break;
            case 'D':
            case 'J':
                popCategory2();
                break;
            case 'L':
            case '[':
                popCategory1();
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

private void pop(final String descriptor){
    int i = descriptor.length() - 1;
    while (i >= 0) {
        char c = descriptor.charAt(i);
        if (c == ')') {
            // Start of method arguments
            i--;
            while (c != '(') {
                c = descriptor.charAt(i);
                popType(c);
                i--;
            }
        } else if (c == '[') {
            // Array type
            while (descriptor.charAt(i) == '[') {
                i--;
            }
            c = descriptor.charAt(i);
            popType(c);
        } else if (c == 'L') {
            // Object type
            i = descriptor.indexOf(';', i) - 1;
        } else {
            // Primitive type
            popType(c);
        }
        i--;
    }
}

private void pop(final String descriptor){
    // Assuming the frame stack is a Stack<Object> named frameStack
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the argument types
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                    frameStack.pop();
                    break;
                case 'L': // class
                case '[': // array
                    frameStack.pop();
                    // Skip the class name or array descriptor
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    break;
            }
            i++;
        }
    } else {
        // It's a field descriptor, pop according to the type
        char c = descriptor.charAt(0);
        switch (c) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                frameStack.pop();
                break;
            case 'L': // class
            case '[': // array
                frameStack.pop();
                break;
        }
    }
}

